const cfg = $('Build Config').first().json;
function h(s) { let x = 5381; for (let i = 0; i < s.length; i++) { x = ((x << 5) + x + s.charCodeAt(i)) | 0; } return (x >>> 0).toString(36); }
function canon(u) {
  const s = String(u || '').split('#')[0];
  const parts = s.split('?');
  const base = parts[0].replace(/\/$/, '');
  let query = '';
  if (parts[1]) {
    const kept = parts[1].split('&').filter(function (p) { const k = p.split('=')[0].toLowerCase(); return k.indexOf('utm_') !== 0 && k !== 'ref' && k !== 'source'; });
    if (kept.length) { query = '?' + kept.join('&'); }
  }
  return (base + query).toLowerCase();
}
function host(u) {
  const m = String(u || '').match(/^https?:\/\/([^\/]+)/i);
  return m ? m[1].replace(/^www\./, '').toLowerCase() : 'unknown';
}
const now = Date.now();
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  if (j.vulnerabilities && Array.isArray(j.vulnerabilities)) {
    for (const v of j.vulnerabilities) {
      const added = Date.parse(v.dateAdded || '');
      if (!added) continue;
      const hours = (now - added) / 3600000;
      if (hours > cfg.maxHours) continue;
      const url = 'https://www.cisa.gov/known-exploited-vulnerabilities-catalog';
      out.push({ title: 'CISA KEV: ' + (v.cveID || '') + ' ' + (v.vendorProject || '') + ' ' + (v.product || '') + ' - ' + (v.vulnerabilityName || ''), url: url + '#' + (v.cveID || ''), source: 'CISA KEV', summary: v.shortDescription || '', published_at: new Date(added).toISOString(), hours_ago: Math.round(hours), category_hint: 'cybersecurity' });
    }
    continue;
  }
  if (j.error) continue;
  const title = (j.title || '').trim();
  const link = j.link || j.url || '';
  if (!title || !link) continue;
  const ts = Date.parse(j.isoDate || j.pubDate || '');
  if (!ts) continue;
  const hours = (now - ts) / 3600000;
  if (hours > cfg.maxHours) continue;
  let t = title;
  let src = host(link);
  let hint = '';
  const gh = link.match(/^https?:\/\/github\.com\/([^\/]+)\/([^\/]+)\/releases\/tag\//i);
  if (gh) {
    src = gh[2] + ' releases';
    hint = 'homelab_selfhosting';
    if (t.toLowerCase().indexOf(gh[2].toLowerCase()) === -1) { t = gh[2] + ' release ' + t; }
  }
  const rd = link.match(/reddit\.com\/r\/([^\/]+)/i);
  if (rd) { src = 'r/' + rd[1]; }
  out.push({ title: t, url: link, source: src, summary: (j.contentSnippet || j.content || '').toString().slice(0, 400), published_at: new Date(ts).toISOString(), hours_ago: Math.round(hours), category_hint: hint });
}
out.sort(function (a, b) { return a.hours_ago - b.hours_ago; });
const seen = out.slice(0, cfg.maxStories).map(function (s) {
  s.freshness = s.hours_ago <= cfg.freshHours ? 'fresh' : '72h';
  s.dedupe_key = h(canon(s.url)) + '-' + h(s.title.toLowerCase().replace(/[^a-z0-9 ]/g, '').replace(/\s+/g, ' ').trim());
  return { json: s };
});
return seen;

const historyKeys = new Set();
for (const item of $input.all()) {
  const j = item.json || {};
  if (j.dedupe_key) historyKeys.add(j.dedupe_key);
}
const seenNow = new Set();
const out = [];
for (const item of $('Normalize Stories').all()) {
  const s = item.json;
  if (historyKeys.has(s.dedupe_key)) continue;
  if (seenNow.has(s.dedupe_key)) continue;
  seenNow.add(s.dedupe_key);
  out.push({ json: s });
}
return out;

const cfg = $('Build Config').first().json;
const stories = $('Dedup Against History').all().map(function (i) { return i.json; });
let emb = null;
try { emb = $input.first().json.embeddings; } catch (e) { emb = null; }
if (!emb || !Array.isArray(emb) || emb.length !== stories.length) {
  return stories.map(function (s) { return { json: s }; });
}
function cos(a, b) {
  let d = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) { d += a[i] * b[i]; na += a[i] * a[i]; nb += b[i] * b[i]; }
  return d / (Math.sqrt(na) * Math.sqrt(nb) || 1);
}
const keep = [];
const keptIdx = [];
for (let i = 0; i < stories.length; i++) {
  let dup = false;
  for (const k of keptIdx) {
    if (cos(emb[i], emb[k]) >= cfg.simThreshold) { dup = true; break; }
  }
  if (!dup) { keep.push(stories[i]); keptIdx.push(i); }
}
return keep.map(function (s) { return { json: s }; });

const cfg = $('Build Config').first().json;
const CATS = ['ai_llm', 'banking_fintech', 'homelab_selfhosting', 'cybersecurity', 'tech_industry', 'excluded'];
const SYS = 'You are a news classifier for a personal tech briefing. Classify the headline into exactly one of these categories: ' +
  'ai_llm (AI models, LLMs, AI tools, AI research and companies); ' +
  'banking_fintech (banking, payments, fintech, treasury, banking AI); ' +
  'homelab_selfhosting (self-hosted apps, home servers, NAS, Proxmox, Docker, Home Assistant, Tailscale, and self-hosted software releases such as n8n, Gitea, Portainer, Uptime Kuma, Beszel, Plex, Navidrome, homelab hardware); ' +
  'cybersecurity (vulnerabilities, exploits, advisories, breaches, patches); ' +
  'tech_industry (general technology business news, hardware, layoffs, products); ' +
  'excluded (politics and legislation, celebrity and entertainment, sports, ordinary crime). ' +
  'Also assign priority 1-5 where 5 = highly relevant to the reader: Anthropic, Claude, MCP, OpenAI, local LLMs, Ollama, n8n, banking AI, payments, Home Assistant, Proxmox, Synology, Docker, Portainer, Gitea, Uptime Kuma, Beszel, Tailscale, Raspberry Pi, and critical actively-exploited security advisories. 1 = generic news. Respond only with JSON.';
const FORMAT = { type: 'object', properties: { category: { type: 'string', enum: CATS }, priority: { type: 'integer', minimum: 1, maximum: 5 }, reason: { type: 'string' } }, required: ['category', 'priority', 'reason'] };
return $input.all().map(function (i) {
  const s = i.json;
  return { json: { story: s, body: { model: cfg.models.classify, stream: false, think: false, format: FORMAT, options: { temperature: 0 }, messages: [{ role: 'system', content: SYS }, { role: 'user', content: 'Headline: ' + s.title + '\nSource: ' + s.source + '\nSummary: ' + (s.summary || '') }] } } };
});

const cfg = $('Build Config').first().json;
const reqs = $('Build Classify Requests').all();
const resps = $input.all();
const EXCLUDE = /(senator|congress|election|parliament|celebrity|pop star|world tour|box office|nfl|nba|mlb|premier league|arrested|indicted|court sentenc)/i;
const BOOST = /(anthropic|claude|mcp|openai|chatgpt|gemini|ollama|local llm|n8n|home assistant|proxmox|synology|docker|portainer|tailscale|raspberry pi|minisforum|beelink|cisa|kev|zero.day|actively exploited)/i;
const all = [];
let classifyFail = 0;
for (let i = 0; i < reqs.length; i++) {
  const s = reqs[i].json.story;
  let parsed = null;
  try { parsed = JSON.parse(resps[i].json.message.content); } catch (e) { parsed = null; }
  if (!parsed || !parsed.category) { classifyFail++; continue; }
  s.category = parsed.category;
  s.priority = Number(parsed.priority) || 1;
  s.reason = parsed.reason || '';
  if (s.category === 'excluded' || EXCLUDE.test(s.title)) continue;
  if (s.category_hint === 'cybersecurity') s.category = 'cybersecurity';
  s.score = s.priority + (BOOST.test(s.title) ? 2 : 0) + (s.freshness === 'fresh' ? 1 : 0);
  all.push(s);
}
all.sort(function (a, b) { return b.score - a.score || a.hours_ago - b.hours_ago; });
const top = all.slice(0, cfg.topCount).map(function (s) { const c = Object.assign({}, s); c.is_top = true; return c; });
const topKeys = new Set(top.map(function (s) { return s.dedupe_key; }));
const rest = all.filter(function (s) { return !topKeys.has(s.dedupe_key); });
function take(cat) { return rest.filter(function (s) { return s.category === cat; }).slice(0, cfg.sectionCap); }
const sections = {
  radar: take('homelab_selfhosting'),
  security: take('cybersecurity'),
  banking: take('banking_fintech'),
  worth: rest.filter(function (s) { return s.category === 'ai_llm' || s.category === 'tech_industry'; }).slice(0, cfg.sectionCap)
};
const dateStr = new Date().toISOString().slice(0, 10);
return [{ json: { date: dateStr, top: top, sections: sections, all: all, stats: { seen: $('Normalize Stories').all().length, new_after_dedup: reqs.length, classify_failures: classifyFail, selected_top: top.length } } }];

const cfg = $('Build Config').first().json;
const SYS = 'You write brief items for a personal daily tech briefing. Use ONLY the facts provided in the input. Do not invent numbers, dates, versions, CVE IDs, or names that are not in the input. The reader is a technology professional who runs a homelab (NAS, Proxmox, Docker, Ollama, n8n, Home Assistant, Tailscale). EDIT THIS READER PROFILE to match your own interests. Write 2-3 sentences per field. Respond only with JSON.';
const FORMAT = { type: 'object', properties: { what_happened: { type: 'string' }, why_it_matters: { type: 'string' }, personal_relevance: { type: 'string' } }, required: ['what_happened', 'why_it_matters', 'personal_relevance'] };
return $input.all().map(function (i) {
  const s = i.json;
  return { json: { story: s, body: { model: cfg.models.write, stream: false, think: false, format: FORMAT, options: { temperature: 0 }, messages: [{ role: 'system', content: SYS }, { role: 'user', content: 'Title: ' + s.title + '\nSource: ' + s.source + '\nPublished: ' + s.published_at + '\nSummary: ' + (s.summary || '(no summary provided)') }] } } };
});

const cfg = $('Build Config').first().json;
const sel = $('Select And Bucket').first().json;
const reqs = $('Build Write Requests').all();
const resps = $input.all();
const CATLABEL = { ai_llm: 'AI & LLMs', banking_fintech: 'Banking & Fintech', homelab_selfhosting: 'Homelab', cybersecurity: 'Security', tech_industry: 'Tech Industry' };
function esc(t) { return String(t || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
function okUrl(u) { return /^https?:\/\//i.test(u || ''); }
const tops = [];
for (let i = 0; i < reqs.length; i++) {
  const s = reqs[i].json.story;
  if (!okUrl(s.url)) continue;
  let w = null;
  try { w = JSON.parse(resps[i].json.message.content); } catch (e) { w = null; }
  if (!w) w = { what_happened: s.summary || s.title, why_it_matters: '', personal_relevance: '' };
  tops.push({ story: s, w: w });
}
const dateNice = new Date().toDateString();
const subject = 'Daily Tech Briefing - ' + sel.date;
const mdL = [];
mdL.push('# Daily Tech Briefing - ' + sel.date);
mdL.push('');
mdL.push('## Top Stories');
for (const t of tops) {
  mdL.push('');
  mdL.push('### ' + t.story.title);
  mdL.push('- Category: ' + (CATLABEL[t.story.category] || t.story.category) + ' | Source: ' + t.story.source + ' | Published: ' + t.story.published_at + ' | Freshness: ' + t.story.freshness);
  mdL.push('- Link: ' + t.story.url);
  mdL.push('- What happened: ' + t.w.what_happened);
  mdL.push('- Why it matters: ' + t.w.why_it_matters);
  mdL.push('- Personal relevance: ' + t.w.personal_relevance);
}
function mdSection(name, arr) {
  mdL.push('');
  mdL.push('## ' + name);
  if (!arr.length) { mdL.push('- Nothing notable today.'); return; }
  for (const s of arr) { mdL.push('- [' + s.title + '](' + s.url + ') - ' + s.source + (s.freshness === '72h' ? ' (72h)' : '')); }
}
mdSection('Homelab Radar', sel.sections.radar);
mdSection('Security Watch', sel.sections.security);
mdSection('Banking & AI Corner', sel.sections.banking);
mdSection('Worth Your Time', sel.sections.worth);
mdL.push('');
mdL.push('---');
mdL.push('Run stats: seen ' + sel.stats.seen + ', new ' + sel.stats.new_after_dedup + ', classify failures ' + sel.stats.classify_failures + '.');
const archiveMd = mdL.join('\n');
let html = '<div style="max-width:640px;margin:0 auto;font-family:Segoe UI,Arial,sans-serif;color:#222;">';
html += '<h1 style="font-size:22px;border-bottom:2px solid #444;padding-bottom:6px;">Daily Tech Briefing</h1>';
html += '<p style="color:#666;margin-top:0;">' + esc(dateNice) + '</p>';
html += '<h2 style="font-size:18px;">Top Stories</h2>';
for (const t of tops) {
  html += '<div style="margin:0 0 18px 0;padding:12px;border:1px solid #ddd;border-radius:8px;">';
  html += '<div style="font-size:11px;text-transform:uppercase;color:#888;">' + esc(CATLABEL[t.story.category] || t.story.category) + ' | ' + esc(t.story.source) + ' | ' + esc(t.story.freshness === 'fresh' ? 'last 24h' : 'last 72h') + '</div>';
  html += '<div style="font-size:16px;font-weight:bold;margin:4px 0;"><a href="' + esc(t.story.url) + '" style="color:#1a4d8f;text-decoration:none;">' + esc(t.story.title) + '</a></div>';
  html += '<p style="margin:6px 0;"><b>What happened:</b> ' + esc(t.w.what_happened) + '</p>';
  html += '<p style="margin:6px 0;"><b>Why it matters:</b> ' + esc(t.w.why_it_matters) + '</p>';
  html += '<p style="margin:6px 0;"><b>For you:</b> ' + esc(t.w.personal_relevance) + '</p>';
  html += '</div>';
}
function htmlSection(name, arr) {
  html += '<h2 style="font-size:18px;">' + esc(name) + '</h2>';
  if (!arr.length) { html += '<p style="color:#888;">Nothing notable today.</p>'; return; }
  html += '<ul style="padding-left:18px;">';
  for (const s of arr) { html += '<li style="margin:4px 0;"><a href="' + esc(s.url) + '" style="color:#1a4d8f;">' + esc(s.title) + '</a> <span style="color:#888;font-size:12px;">' + esc(s.source) + (s.freshness === '72h' ? ' (72h)' : '') + '</span></li>'; }
  html += '</ul>';
}
htmlSection('Homelab Radar', sel.sections.radar);
htmlSection('Security Watch', sel.sections.security);
htmlSection('Banking & AI Corner', sel.sections.banking);
htmlSection('Worth Your Time', sel.sections.worth);
html += '<p style="color:#aaa;font-size:11px;">Generated by n8n. Stats: ' + sel.stats.seen + ' seen, ' + sel.stats.new_after_dedup + ' new.</p></div>';
const chunks = [];
let cur = '**Daily Tech Briefing - ' + sel.date + '**\n';
function push(line) { if ((cur + line).length > 1900) { chunks.push(cur); cur = ''; } cur += line + '\n'; }
for (const t of tops) { push('**' + t.story.title + '**'); push('<' + t.story.url + '> | ' + (CATLABEL[t.story.category] || t.story.category)); push(t.w.what_happened); push(''); }
function dSection(name, arr) { if (!arr.length) return; push('__' + name + '__'); for (const s of arr) { push('- ' + s.title + ' <' + s.url + '>'); } push(''); }
dSection('Homelab Radar', sel.sections.radar);
dSection('Security Watch', sel.sections.security);
dSection('Banking & AI Corner', sel.sections.banking);
dSection('Worth Your Time', sel.sections.worth);
if (cur.trim()) chunks.push(cur);
const nowIso = new Date().toISOString();
const rows = sel.all.map(function (s) { return { dedupe_key: s.dedupe_key, url: s.url, title: s.title.slice(0, 250), source: s.source, category: s.category, published_at: s.published_at, first_seen: nowIso }; });
return [{ json: { subject: subject, email_html: html, email_text: archiveMd, chunks: chunks, archive_md: archiveMd, archive_json: JSON.stringify({ date: sel.date, top: tops, sections: sel.sections, stats: sel.stats }, null, 2), md_path: cfg.vaultBase + sel.date + '.md', json_path: cfg.vaultBase + sel.date + '.json', rows: rows } }];
